:root {
  --bg: #1b1e2b;
  --card: #262a3d;
  --board: #0f111a;
  --accent: #6ee7b7;
  --accent-dark: #34d399;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --danger: #f87171;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at top, #2a2f45, var(--bg));
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 20px;
  width: 100%;
  max-width: 460px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

h1 {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 0.5px;
}

.score {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--accent);
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: var(--board);
  border-radius: 12px;
  image-rendering: pixelated;
  border: 2px solid #3b415c;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15, 17, 26, 0.85);
  border-radius: 12px;
  text-align: center;
  padding: 16px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  display: none;
}

.overlay-inner h2 {
  margin: 0 0 8px;
  font-size: 1.4rem;
  color: var(--accent);
}

.overlay-inner p {
  margin: 0 0 16px;
  line-height: 1.5;
  color: var(--text);
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 12px 20px;
  border-radius: 10px;
  border: 2px solid #3b415c;
  background: #2f3450;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
}

.btn:hover {
  background: #3a4060;
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
  background: #252a40;
}

.btn.primary {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
  color: #0f111a;
}

.btn.primary:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.controls .btn {
  flex: 1 1 140px;
}

.hint {
  margin: 0;
  font-size: 0.95rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .score { font-size: 1rem; }
}

(function () {
  'use strict';

  const canvas = document.getElementById('board');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 130;

  const COLORS = {
    snake: '#6ee7b7',
    head: '#34d399',
    food: '#f87171',
    grid: '#1a1d2b'
  };

  let snake, dir, nextDir, food, score;
  let status = 'paused'; // 'paused' | 'playing' | 'gameover'
  let timer = null;

  function reset() {
    snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    status = 'paused';
    stopTimer();
    setPauseLabel();
    draw();
  }

  function placeFood() {
    const free = [];
    for (let y = 0; y < GRID; y++) {
      for (let x = 0; x < GRID; x++) {
        if (!snake.some(s => s.x === x && s.y === y)) free.push({ x, y });
      }
    }
    food = free[Math.floor(Math.random() * free.length)] || { x: 0, y: 0 };
  }

  function draw() {
    ctx.fillStyle = COLORS.grid;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    // food
    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 2, food.y * CELL + 2, CELL - 4, CELL - 4);

    // snake
    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function step() {
    if (status !== 'playing') return;

    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    // wall collision
    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      return gameOver();
    }
    // self collision (ignore tail that will move)
    if (snake.some((s, i) => i < snake.length - 1 && s.x === head.x && s.y === head.y)) {
      return gameOver();
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(step, TICK_MS);
  }

  function stopTimer() {
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  }

  function setPauseLabel() {
    pauseBtn.textContent = status === 'playing' ? 'Pause' : 'Resume';
    pauseBtn.setAttribute('aria-label', status === 'playing' ? 'Pause game' : 'Resume game');
  }

  function startGame() {
    if (status === 'gameover') reset();
    status = 'playing';
    overlay.classList.add('hidden');
    setPauseLabel();
    startTimer();
  }

  function pauseGame() {
    if (status !== 'playing') return;
    status = 'paused';
    stopTimer();
    setPauseLabel();
    showOverlay('Paused', 'Press Resume or Space to continue.', 'Resume');
  }

  function resumeGame() {
    if (status === 'paused') startGame();
  }

  function togglePause() {
    if (status === 'playing') pauseGame();
    else if (status === 'paused') resumeGame();
  }

  function gameOver() {
    status = 'gameover';
    stopTimer();
    setPauseLabel();
    showOverlay('Game Over', 'Final score: ' + score + '. Press Restart to play again.', 'Restart');
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
  }

  function restart() {
    reset();
    showOverlay('How to Play', 'Use <strong>Arrow Keys</strong> to move. Press <strong>Space</strong> or the button to pause/resume.', 'Start Game');
  }

  // --- Input ---
  const KEY_DIRS = {
    ArrowUp: { x: 0, y: -1 },
    ArrowDown: { x: 0, y: 1 },
    ArrowLeft: { x: -1, y: 0 },
    ArrowRight: { x: 1, y: 0 }
  };

  document.addEventListener('keydown', (e) => {
    if (e.key === ' ' || e.key === 'Spacebar') {
      e.preventDefault();
      if (status === 'gameover') return;
      togglePause();
      return;
    }

    const nd = KEY_DIRS[e.key];
    if (!nd) return;
    e.preventDefault();

    if (status === 'paused') {
      // allow starting with an arrow direction
      if (overlay.classList.contains('hidden') === false) startGame();
    }
    if (status === 'gameover') return;

    // prevent reversing into self
    if (nd.x === -dir.x && nd.y === -dir.y) return;
    nextDir = nd;
  });

  overlayBtn.addEventListener('click', () => {
    if (status === 'gameover') {
      reset();
      startGame();
    } else {
      startGame();
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', () => {
    reset();
    showOverlay('How to Play', 'Use <strong>Arrow Keys</strong> to move. Press <strong>Space</strong> or the button to pause/resume.', 'Start Game');
  });

  // --- Init ---
  reset();
  showOverlay('How to Play', 'Use <strong>Arrow Keys</strong> to move. Press <strong>Space</strong> or the button to pause/resume.', 'Start Game');
})();
